WITH run AS (
  INSERT INTO engine_runs (engine, session_id, input, output, risk_level, status)
  VALUES ($1, $2, $3, $4::jsonb, $5, $6)
), leads AS (
  INSERT INTO crm_leads (name, email, phone, company, status, interest_score, context)
  SELECT c->>'name', c->>'email', c->>'phone', c->>'company', 'new',
         NULLIF(regexp_replace(COALESCE(c->>'score', ''), '[^0-9]', '', 'g'), '')::int, 'Lead-Engine'
  FROM jsonb_array_elements($7::jsonb) AS c
  RETURNING 1
), usage AS (
  INSERT INTO llm_usage (workflow, input_chars, output_chars, est_cost_eur) VALUES ('ENGINE_HUB', $8, $9, emma_llm_cost($8, $9))
)
SELECT (SELECT count(*) FROM leads) AS leads_created;

